// Storyboard-only local LLM integration: no image or video model is run.
import {canReplaceDefaultStoryboard,storyboardFromSongSections} from './songStoryboard.js';
import {auditMvStoryboard} from './mvStoryboard.js';
const snapshot=p=>JSON.stringify([p.id,p.scenes,p.sections,p.bpm,p.prompt,p.lyrics,p.characterId]);
// New projects generated by the existing Create97 pipeline already contain
// pristine auto storyboard scenes. Allow them, but never replace edited scenes.
export function canApplyLocalAiStoryboard(project){
 if(canReplaceDefaultStoryboard(project))return true;
 try{
  const expected=storyboardFromSongSections(project);
  return JSON.stringify(project.scenes)===JSON.stringify(expected);
 }catch{return false}
}
const validModel=s=>typeof s==='string'&&/^[a-zA-Z0-9][a-zA-Z0-9_.:/-]{0,119}$/.test(s);
export async function planLocalAiStoryboard(project,model,{fetchImpl=fetch,key=globalThis.__MYVOCAL_SESSION_KEY}={}){
 if(!project?.id||!canApplyLocalAiStoryboard(project))throw Error('이미 편집했거나 이미지가 연결된 장면은 자동으로 덮어쓰지 않습니다. 빈 기본 장면의 프로젝트에서 실행하세요.');
 if(!validModel(model))throw Error('설치된 로컬 모델을 선택해야 합니다.');
 if(typeof key!=='string'||!key)throw Error('Windows EXE에서만 로컬 AI 연결이 가능합니다.');
 if(!Array.isArray(project.sections)||project.sections.length>20)throw Error('콘티 자동 생성은 구간 1~20개까지만 지원합니다.');
 const proposed=storyboardFromSongSections(project);
 const stamp=snapshot(project);
 const response=await fetchImpl('/api/local-ai/storyboard',{method:'POST',headers:{'Content-Type':'application/json','X-MYVOCAL-Session':key},cache:'no-store',body:JSON.stringify({model,prompt:String(project.prompt||project.title||''),lyrics:String(project.lyrics||'').slice(0,8000),sections:project.sections.map(s=>({name:s.name,bars:s.bars}))})});
 const result=await response.json().catch(()=>null);
 if(!response.ok)throw Error(result?.error||`로컬 AI 콘티 생성 오류: ${response.status}`);
 if(result?.provider!=='local-ollama'||result.model!==model||result.textGenerated!==true||result.videoGenerated!==false||!Array.isArray(result.scenes)||result.scenes.length!==proposed.length)throw Error('AI 콘티 형식 또는 장면 수가 올바르지 않습니다.');
 const str=(v,max)=>typeof v==='string'&&v.length<=max&&!/[\u0000-\u001f\u007f]/.test(v);
 const scenes=proposed.map((scene,i)=>{
  const v=result.scenes[i];if(!v||!str(v.title,120)||!v.title.trim()||!str(v.description,1200)||!str(v.location,200)||!str(v.action,200)||!str(v.camera,200)||!str(v.lighting,200))throw Error('생성된 장면 설명을 사용할 수 없습니다.');
  return {...scene,title:v.title,description:v.description,location:v.location,action:v.action,camera:v.camera,lighting:v.lighting};
 });
 if(auditMvStoryboard({...project,scenes}).errors)throw Error('생성된 콘티에 시간 충돌이 있습니다.');
 return {format:'MYVOCAL_LOCAL_AI_STORYBOARD',projectId:project.id,source:stamp,model,scenes,videoGenerated:false};
}
export function applyLocalAiStoryboard(project,plan){
 if(plan?.format!=='MYVOCAL_LOCAL_AI_STORYBOARD'||plan.projectId!==project?.id||plan.source!==snapshot(project)||!canApplyLocalAiStoryboard(project))throw Error('콘티 미리보기 이후 원본 장면이 변경됐습니다. 다시 생성해 주세요.');
 if(auditMvStoryboard({...project,scenes:plan.scenes}).errors)throw Error('장면 시간 또는 원본 정보가 손상됐습니다.');
 return {...project,scenes:plan.scenes,localAiStoryboard:{model:plan.model,source:'local-ollama',videoGenerated:false,generatedAt:new Date().toISOString()}};
}